V = TypeVar("V", bound=Hashable)

def audit_linear_intersecting(edges: Iterable[Iterable[V]]) -> dict[str, object]:
    data = [frozenset(edge) for edge in edges]
    sizes = {len(edge) for edge in data}
    violations: list[tuple[int, int, int]] = []
    for i, j in combinations(range(len(data)), 2):
        overlap = len(data[i] & data[j])
        if overlap != 1:
            violations.append((i, j, overlap))
    rank = next(iter(sizes)) if len(sizes) == 1 else None
    return {"uniform_rank": rank, "exact_intersection": not violations,
            "violations": violations}

from __future__ import annotations
from typing import Hashable, Iterable, TypeVar

V = TypeVar("V", bound=Hashable)

def build_contact_map(edges: Iterable[Iterable[V]], reference: int) -> dict[V, list[int]]:
    data = [frozenset(edge) for edge in edges]
    base = data[reference]
    result: dict[V, list[int]] = {x: [] for x in base}
    for i, edge in enumerate(data):
        if i == reference:
            continue
        contact = base & edge
        if len(contact) != 1:
            raise ValueError(f"edge pair ({reference}, {i}) has {len(contact)} contacts")
        result[next(iter(contact))].append(i)
    return result

from __future__ import annotations
from typing import Hashable, Iterable, TypeVar

V = TypeVar("V", bound=Hashable)

def audit_all_stars(edges: Iterable[Iterable[V]]) -> tuple[bool, tuple[V, int, int] | None]:
    data = [frozenset(edge) for edge in edges]
    incidence: dict[V, list[int]] = {}
    for i, edge in enumerate(data):
        for x in edge:
            incidence.setdefault(x, []).append(i)
    for center, indices in incidence.items():
        owner: dict[V, int] = {}
        for i in indices:
            for y in data[i] - {center}:
                if y in owner:
                    return False, (center, owner[y], i)
                owner[y] = i
    return True, None

